insert into public.curated_courses (id, slug, title, description)
insert into public.curated_course_nodes (id, course_id, parent_id, node_type, title, description, sort_order)
values
  ('20798afc-aadb-4a2a-b8fd-ec1d204d01a6', 'e9f0a1b2-3c4d-4e44-9a34-4b5c6d7e8f44', null, 'topic'::public.curated_course_node_type, 'Editing as Cinematic Language', 'Students learn that editing is not only technical assembly; it is the central language of time, attention, emotion, causality, and meaning in moving images.', 0),
  ('59aef3e6-2deb-42d6-8a7a-6d7c0d3af5eb', 'e9f0a1b2-3c4d-4e44-9a34-4b5c6d7e8f44', '20798afc-aadb-4a2a-b8fd-ec1d204d01a6', 'subtopic'::public.curated_course_node_type, 'The grammar of the cut', 'This subtopic introduces the cut as a meaningful relation between shots, not just a way to remove unwanted footage.', 0),
  ('c28f27b4-5f75-45db-98b9-78e5077ad56c', 'e9f0a1b2-3c4d-4e44-9a34-4b5c6d7e8f44', '59aef3e6-2deb-42d6-8a7a-6d7c0d3af5eb', 'concept'::public.curated_course_node_type, 'Shot, take, setup, sequence, scene, transition, and ellipsis', null, 0),
  ('3f698e01-f16f-4cac-b227-322707dc7f22', 'e9f0a1b2-3c4d-4e44-9a34-4b5c6d7e8f44', '59aef3e6-2deb-42d6-8a7a-6d7c0d3af5eb', 'concept'::public.curated_course_node_type, 'Cut on action, match cut, jump cut, smash cut, L-cut, J-cut, and dissolve', null, 1),
  ('3227549d-65d0-4a04-abf1-dad67c844a73', 'e9f0a1b2-3c4d-4e44-9a34-4b5c6d7e8f44', '59aef3e6-2deb-42d6-8a7a-6d7c0d3af5eb', 'concept'::public.curated_course_node_type, 'Screen direction, eyeline, point of view, emphasis, and narrative clarity', null, 2),
  ('7f5bc54d-e55f-4510-af05-850176c703a1', 'e9f0a1b2-3c4d-4e44-9a34-4b5c6d7e8f44', '20798afc-aadb-4a2a-b8fd-ec1d204d01a6', 'subtopic'::public.curated_course_node_type, 'Time, duration, and attention', 'Students learn how editors compress, expand, reorder, and guide time so viewers feel story rather than merely receive information.', 1),
  ('8b5d6905-2d77-4e15-b3f3-f29b01226235', 'e9f0a1b2-3c4d-4e44-9a34-4b5c6d7e8f44', '7f5bc54d-e55f-4510-af05-850176c703a1', 'concept'::public.curated_course_node_type, 'Real time, compressed time, expanded time, flashback, flashforward, and parallel action', null, 0),
  ('67e5933a-beae-47da-9b8b-b8c4c8190627', 'e9f0a1b2-3c4d-4e44-9a34-4b5c6d7e8f44', '7f5bc54d-e55f-4510-af05-850176c703a1', 'concept'::public.curated_course_node_type, 'Attention management, withholding, reveal, surprise, suspense, and expectation', null, 1),
  ('863faab3-dd6b-4a78-b730-48f827a26065', 'e9f0a1b2-3c4d-4e44-9a34-4b5c6d7e8f44', '7f5bc54d-e55f-4510-af05-850176c703a1', 'concept'::public.curated_course_node_type, 'Rhythmic density, visual contrast, and perceptual load', null, 2),
  ('3db9b235-2a14-4b9d-a765-502ffc837b0b', 'e9f0a1b2-3c4d-4e44-9a34-4b5c6d7e8f44', '20798afc-aadb-4a2a-b8fd-ec1d204d01a6', 'subtopic'::public.curated_course_node_type, 'Meaning through relation', 'This section shows how meaning often emerges between shots through juxtaposition, association, and audience inference.', 2),
  ('505191a4-bbf3-421f-92e5-11e98c12dfb8', 'e9f0a1b2-3c4d-4e44-9a34-4b5c6d7e8f44', '3db9b235-2a14-4b9d-a765-502ffc837b0b', 'concept'::public.curated_course_node_type, 'Kuleshov effect, montage theory, intellectual montage, and associative editing', null, 0),
  ('787b0b79-b0f0-4ece-a033-4c9e23b43436', 'e9f0a1b2-3c4d-4e44-9a34-4b5c6d7e8f44', '3db9b235-2a14-4b9d-a765-502ffc837b0b', 'concept'::public.curated_course_node_type, 'Emotional, spatial, graphic, rhythmic, and thematic relationships', null, 1),
  ('0e0b11b2-1a23-411d-9c19-53a5f4937fbb', 'e9f0a1b2-3c4d-4e44-9a34-4b5c6d7e8f44', '3db9b235-2a14-4b9d-a765-502ffc837b0b', 'concept'::public.curated_course_node_type, 'When clarity matters and when productive ambiguity matters', null, 2),
  ('87216c16-cf93-4144-9352-b2ed645a5c97', 'e9f0a1b2-3c4d-4e44-9a34-4b5c6d7e8f44', null, 'topic'::public.curated_course_node_type, 'Story Analysis, Dailies, Coverage, and Editorial Judgment', 'Students learn how editors read footage, diagnose story problems, evaluate performances, and form a plan before building a cut.', 1),
  ('aee28908-0357-4089-b5a7-1372f6fb9ef6', 'e9f0a1b2-3c4d-4e44-9a34-4b5c6d7e8f44', '87216c16-cf93-4144-9352-b2ed645a5c97', 'subtopic'::public.curated_course_node_type, 'Reading footage critically', 'The goal is to see what the footage can actually do, not what the script or shoot plan hoped it would do.', 0),
  ('d3bf35d2-0913-4311-b44f-c324ca128335', 'e9f0a1b2-3c4d-4e44-9a34-4b5c6d7e8f44', 'aee28908-0357-4089-b5a7-1372f6fb9ef6', 'concept'::public.curated_course_node_type, 'Dailies review, circle takes, continuity notes, script supervisor notes, and director comments', null, 0),
  ('8cc2544d-da4e-4859-b9b5-94e4cf7bc790', 'e9f0a1b2-3c4d-4e44-9a34-4b5c6d7e8f44', 'aee28908-0357-4089-b5a7-1372f6fb9ef6', 'concept'::public.curated_course_node_type, 'Performance, blocking, camera movement, focus, exposure, sound, and usability', null, 1),
  ('c433a866-0597-4195-acf8-1a6b3a326fdc', 'e9f0a1b2-3c4d-4e44-9a34-4b5c6d7e8f44', 'aee28908-0357-4089-b5a7-1372f6fb9ef6', 'concept'::public.curated_course_node_type, 'Discovering story opportunities, missing beats, and unexpected strengths', null, 2),
  ('3c2eda19-d51a-477d-9926-7159aa9bd119', 'e9f0a1b2-3c4d-4e44-9a34-4b5c6d7e8f44', '87216c16-cf93-4144-9352-b2ed645a5c97', 'subtopic'::public.curated_course_node_type, 'Coverage and scene options', 'Students learn to assess coverage as a set of storytelling possibilities and constraints.', 1),
  ('59fde2b3-8c0b-4bba-b8e0-ace814be581a', 'e9f0a1b2-3c4d-4e44-9a34-4b5c6d7e8f44', '3c2eda19-d51a-477d-9926-7159aa9bd119', 'concept'::public.curated_course_node_type, 'Masters, singles, over-the-shoulders, inserts, cutaways, reaction shots, and wild lines', null, 0),
  ('f5e9bf99-2e86-4102-9855-5e174ccf02f7', 'e9f0a1b2-3c4d-4e44-9a34-4b5c6d7e8f44', '3c2eda19-d51a-477d-9926-7159aa9bd119', 'concept'::public.curated_course_node_type, 'Beat mapping, emotional turns, entrances, exits, and scene objectives', null, 1),
  ('c1aa0ff0-d5c5-4334-abb4-fb65479f5626', 'e9f0a1b2-3c4d-4e44-9a34-4b5c6d7e8f44', '3c2eda19-d51a-477d-9926-7159aa9bd119', 'concept'::public.curated_course_node_type, 'Using coverage to solve pacing, clarity, continuity, and performance problems', null, 2),
  ('25d469d0-e1c3-4daa-bb81-5ba0afa2efa6', 'e9f0a1b2-3c4d-4e44-9a34-4b5c6d7e8f44', '87216c16-cf93-4144-9352-b2ed645a5c97', 'subtopic'::public.curated_course_node_type, 'Editorial judgment', 'This subtopic frames editing as a sequence of choices about story priority, audience experience, and collaboration.', 2),
  ('a15564f0-ba7b-43e6-9127-e24419351f0f', 'e9f0a1b2-3c4d-4e44-9a34-4b5c6d7e8f44', '25d469d0-e1c3-4daa-bb81-5ba0afa2efa6', 'concept'::public.curated_course_node_type, 'Intention, point of view, tone, stakes, character alignment, and audience empathy', null, 0),
  ('c70dadf7-4338-4e9e-9bf2-f5ad53d7185b', 'e9f0a1b2-3c4d-4e44-9a34-4b5c6d7e8f44', '25d469d0-e1c3-4daa-bb81-5ba0afa2efa6', 'concept'::public.curated_course_node_type, 'Cutting for story over favorite shots, beautiful images, or technical perfection', null, 1),
  ('b28cdc43-c7a3-4ba9-946a-ebbcc5431205', 'e9f0a1b2-3c4d-4e44-9a34-4b5c6d7e8f44', '25d469d0-e1c3-4daa-bb81-5ba0afa2efa6', 'concept'::public.curated_course_node_type, 'Making defensible creative decisions and explaining them in critique', null, 2),
  ('50a6eee4-b198-4f11-b4c6-6e1e1ec7e5aa', 'e9f0a1b2-3c4d-4e44-9a34-4b5c6d7e8f44', null, 'topic'::public.curated_course_node_type, 'Nonlinear Editing Workflow and Assistant Editor Foundations', 'Students build professional habits for ingesting, organizing, syncing, backing up, editing, and handing off media in modern NLE environments.', 2),
  ('603564da-1ace-485d-b335-37ea801f2dca', 'e9f0a1b2-3c4d-4e44-9a34-4b5c6d7e8f44', '50a6eee4-b198-4f11-b4c6-6e1e1ec7e5aa', 'subtopic'::public.curated_course_node_type, 'Project setup and media management', 'This subtopic teaches the invisible organization that keeps creative editing from becoming technical chaos.', 0),
  ('1114e33d-440e-4416-b25b-3125f95030c1', 'e9f0a1b2-3c4d-4e44-9a34-4b5c6d7e8f44', '603564da-1ace-485d-b335-37ea801f2dca', 'concept'::public.curated_course_node_type, 'Folder structures, project settings, naming conventions, bins, markers, and metadata', null, 0),
  ('01e2c145-b7c1-41d5-9ac5-371585849476', 'e9f0a1b2-3c4d-4e44-9a34-4b5c6d7e8f44', '603564da-1ace-485d-b335-37ea801f2dca', 'concept'::public.curated_course_node_type, 'Camera originals, proxies, transcoding, optimized media, relinking, and offline/online workflow', null, 1),
  ('590a174b-319a-4290-92c7-a7824192c29c', 'e9f0a1b2-3c4d-4e44-9a34-4b5c6d7e8f44', '603564da-1ace-485d-b335-37ea801f2dca', 'concept'::public.curated_course_node_type, '3-2-1 backup thinking, checksums, drive management, and version control', null, 2),
  ('a2c57ab8-cba3-49d7-8c7d-a972d2ae325f', 'e9f0a1b2-3c4d-4e44-9a34-4b5c6d7e8f44', '50a6eee4-b198-4f11-b4c6-6e1e1ec7e5aa', 'subtopic'::public.curated_course_node_type, 'Sync, selects, and assistant workflows', 'Students learn the assistant editor practices that make an edit room fast, reliable, and collaborative.', 1),
  ('b66cc044-d97c-4039-b32b-452e74f9748f', 'e9f0a1b2-3c4d-4e44-9a34-4b5c6d7e8f44', 'a2c57ab8-cba3-49d7-8c7d-a972d2ae325f', 'concept'::public.curated_course_node_type, 'Audio sync, multicam sync, slates, timecode, waveform sync, and grouped clips', null, 0),
  ('d0c4c2fd-e32e-4620-a172-3d0f4e873a05', 'e9f0a1b2-3c4d-4e44-9a34-4b5c6d7e8f44', 'a2c57ab8-cba3-49d7-8c7d-a972d2ae325f', 'concept'::public.curated_course_node_type, 'Selects reels, stringouts, scene bins, script sync, markers, and annotations', null, 1),
  ('8767dc72-0d5a-48cc-a5e4-e528b2fb404d', 'e9f0a1b2-3c4d-4e44-9a34-4b5c6d7e8f44', 'a2c57ab8-cba3-49d7-8c7d-a972d2ae325f', 'concept'::public.curated_course_node_type, 'Turnover prep, EDL/XML/AAF/OMF basics, project sharing, and handoff etiquette', null, 2),
  ('97af2f3c-6b5c-43a7-b3ae-0f8183d208c7', 'e9f0a1b2-3c4d-4e44-9a34-4b5c6d7e8f44', '50a6eee4-b198-4f11-b4c6-6e1e1ec7e5aa', 'subtopic'::public.curated_course_node_type, 'Professional NLE fluency', 'The course treats software as a craft environment: students should understand concepts that transfer across Premiere, Resolve, Avid, and Final Cut.', 2),
  ('4b360631-4048-463e-910a-8b4228a12bcf', 'e9f0a1b2-3c4d-4e44-9a34-4b5c6d7e8f44', '97af2f3c-6b5c-43a7-b3ae-0f8183d208c7', 'concept'::public.curated_course_node_type, 'Timelines, tracks, nesting, multicam, source/record editing, trimming, and keyboard shortcuts', null, 0),
  ('d1368785-9474-4299-adcc-80016b2aa171', 'e9f0a1b2-3c4d-4e44-9a34-4b5c6d7e8f44', '97af2f3c-6b5c-43a7-b3ae-0f8183d208c7', 'concept'::public.curated_course_node_type, 'Effects pipelines, adjustment layers, speed changes, stabilization, and basic compositing', null, 1),
  ('c58bbde6-c78a-412a-a01d-0dfedc9b1f8c', 'e9f0a1b2-3c4d-4e44-9a34-4b5c6d7e8f44', '97af2f3c-6b5c-43a7-b3ae-0f8183d208c7', 'concept'::public.curated_course_node_type, 'Export settings, render management, project cleanup, and troubleshooting', null, 2),
  ('590b9356-d249-429b-90b5-689ee1bdf78a', 'e9f0a1b2-3c4d-4e44-9a34-4b5c6d7e8f44', null, 'topic'::public.curated_course_node_type, 'Continuity Editing, Spatial Clarity, and Performance Construction', 'Students learn classical continuity as a powerful system for clarity, then learn how and when to bend it.', 3);
insert into public.curated_course_nodes (id, course_id, parent_id, node_type, title, description, sort_order)
values
  ('2238a403-2c89-4574-b343-bd3ea9182d04', 'e9f0a1b2-3c4d-4e44-9a34-4b5c6d7e8f44', '590b9356-d249-429b-90b5-689ee1bdf78a', 'subtopic'::public.curated_course_node_type, 'Classical continuity systems', 'This subtopic teaches the conventions that help viewers understand space, action, and character intention without confusion.', 0),
  ('132088a6-a07b-4335-b80f-800ae2bf5e98', 'e9f0a1b2-3c4d-4e44-9a34-4b5c6d7e8f44', '2238a403-2c89-4574-b343-bd3ea9182d04', 'concept'::public.curated_course_node_type, '180-degree rule, 30-degree rule, shot/reverse shot, eyeline match, and matching action', null, 0),
  ('d78df535-de18-4d6a-bc10-09d0320b1471', 'e9f0a1b2-3c4d-4e44-9a34-4b5c6d7e8f44', '2238a403-2c89-4574-b343-bd3ea9182d04', 'concept'::public.curated_course_node_type, 'Establishing geography, entrances and exits, eye traces, and screen direction', null, 1),
  ('4a9c87ec-0889-4e71-a856-1c34a4225f96', 'e9f0a1b2-3c4d-4e44-9a34-4b5c6d7e8f44', '2238a403-2c89-4574-b343-bd3ea9182d04', 'concept'::public.curated_course_node_type, 'Cutaways, inserts, reaction shots, and continuity repair', null, 2),
  ('1f76adc6-0556-474e-9b3e-ba538a5a41e8', 'e9f0a1b2-3c4d-4e44-9a34-4b5c6d7e8f44', '590b9356-d249-429b-90b5-689ee1bdf78a', 'subtopic'::public.curated_course_node_type, 'Performance shaping', 'Students learn that editors often build performances from many takes, pauses, reactions, and rhythms.', 1),
  ('f092a8b5-e27c-4371-a0ba-2ec8cd0ad86d', 'e9f0a1b2-3c4d-4e44-9a34-4b5c6d7e8f44', '1f76adc6-0556-474e-9b3e-ba538a5a41e8', 'concept'::public.curated_course_node_type, 'Choosing takes for intention, listening, subtext, vulnerability, and energy', null, 0),
  ('1fd78cdd-f69a-4316-b882-956afcb67171', 'e9f0a1b2-3c4d-4e44-9a34-4b5c6d7e8f44', '1f76adc6-0556-474e-9b3e-ba538a5a41e8', 'concept'::public.curated_course_node_type, 'Combining dialogue, pauses, reactions, overlaps, and breath', null, 1),
  ('9219139f-a3c4-4de8-aeb8-f96148345426', 'e9f0a1b2-3c4d-4e44-9a34-4b5c6d7e8f44', '1f76adc6-0556-474e-9b3e-ba538a5a41e8', 'concept'::public.curated_course_node_type, 'Respecting actors while shaping the emotional truth of the scene', null, 2),
  ('14e62d5e-ef98-4e6e-844d-6320261cb1ea', 'e9f0a1b2-3c4d-4e44-9a34-4b5c6d7e8f44', '590b9356-d249-429b-90b5-689ee1bdf78a', 'subtopic'::public.curated_course_node_type, 'Breaking continuity with purpose', 'This section helps students distinguish expressive discontinuity from accidental confusion.', 2),
  ('1e811b7e-7692-4c26-b0a3-3c5113657528', 'e9f0a1b2-3c4d-4e44-9a34-4b5c6d7e8f44', '14e62d5e-ef98-4e6e-844d-6320261cb1ea', 'concept'::public.curated_course_node_type, 'Jump cuts, temporal fragmentation, subjective editing, and spatial disorientation', null, 0),
  ('14a76689-5254-4b99-b4ca-c20da3cc85fa', 'e9f0a1b2-3c4d-4e44-9a34-4b5c6d7e8f44', '14e62d5e-ef98-4e6e-844d-6320261cb1ea', 'concept'::public.curated_course_node_type, 'Experimental, comedic, horror, action, documentary, and music-video uses', null, 1),
  ('b9a17d03-be42-4749-a9ff-3b74f9270fb1', 'e9f0a1b2-3c4d-4e44-9a34-4b5c6d7e8f44', '14e62d5e-ef98-4e6e-844d-6320261cb1ea', 'concept'::public.curated_course_node_type, 'Audience contract, genre expectation, and intentional rule breaking', null, 2),
  ('d04516f4-7452-4822-ba18-11533a6aa990', 'e9f0a1b2-3c4d-4e44-9a34-4b5c6d7e8f44', null, 'topic'::public.curated_course_node_type, 'Rhythm, Pacing, Scene Shape, and Emotional Momentum', 'Students develop the editor''s ear for timing: when to cut, when to hold, when to breathe, and when to accelerate.', 4),
  ('cabca284-0e8c-4ec4-8481-e2b2e514c41e', 'e9f0a1b2-3c4d-4e44-9a34-4b5c6d7e8f44', 'd04516f4-7452-4822-ba18-11533a6aa990', 'subtopic'::public.curated_course_node_type, 'Pacing and scene architecture', 'This subtopic teaches students to shape scenes around beats, turns, escalation, and release.', 0),
  ('76d8c975-eb5d-43e2-bbf9-6ec373d1eda8', 'e9f0a1b2-3c4d-4e44-9a34-4b5c6d7e8f44', 'cabca284-0e8c-4ec4-8481-e2b2e514c41e', 'concept'::public.curated_course_node_type, 'Opening beat, inciting pressure, reversals, reveals, climax, and button', null, 0),
  ('c4ade5bd-c11c-4c9e-a0b0-686b92d4924c', 'e9f0a1b2-3c4d-4e44-9a34-4b5c6d7e8f44', 'cabca284-0e8c-4ec4-8481-e2b2e514c41e', 'concept'::public.curated_course_node_type, 'Scene length, silence, pauses, overlaps, and visual breathing room', null, 1),
  ('525449dd-ef02-4a69-9199-e39b52f72ae0', 'e9f0a1b2-3c4d-4e44-9a34-4b5c6d7e8f44', 'cabca284-0e8c-4ec4-8481-e2b2e514c41e', 'concept'::public.curated_course_node_type, 'Cutting entrances, exits, repetition, dead air, and redundant information', null, 2),
  ('0b850bae-7dd4-4fbb-8acf-65057437e60f', 'e9f0a1b2-3c4d-4e44-9a34-4b5c6d7e8f44', 'd04516f4-7452-4822-ba18-11533a6aa990', 'subtopic'::public.curated_course_node_type, 'Rhythm across image and sound', 'Students learn that rhythm is built from picture, performance, sound, music, camera movement, and audience expectation.', 1),
  ('ffb0c367-1972-4613-87e6-3ae97f2cb8b4', 'e9f0a1b2-3c4d-4e44-9a34-4b5c6d7e8f44', '0b850bae-7dd4-4fbb-8acf-65057437e60f', 'concept'::public.curated_course_node_type, 'Internal rhythm, external rhythm, musical rhythm, visual rhythm, and dialogue rhythm', null, 0),
  ('08450179-5238-4513-8667-9b0cc9044f61', 'e9f0a1b2-3c4d-4e44-9a34-4b5c6d7e8f44', '0b850bae-7dd4-4fbb-8acf-65057437e60f', 'concept'::public.curated_course_node_type, 'Action cutting, comedy timing, horror timing, trailer pacing, and contemplative pacing', null, 1),
